class Solution {
    public int findKthLargest(int[] nums, int k) {
        PriorityQueue<Integer> heap = new PriorityQueue<>();
        for (int num : nums) {
            heap.add(num);
            if (heap.size() > k) {
                heap.poll();
            }
        }
        return heap.peek();
    }
}

def find_kth_largest(nums, k):
    # Quickselect-style partition: O(n) average, and it teaches the same idea the pattern is about.
    values = list(nums)
    target = len(values) - k
    low, high = 0, len(values) - 1
    while low <= high:
        pivot = values[high]
        store = low
        for index in range(low, high):
            if values[index] < pivot:
                values[store], values[index] = values[index], values[store]
                store += 1
        values[store], values[high] = values[high], values[store]
        if store == target:
            return values[store]
        if store < target:
            low = store + 1
        else:
            high = store - 1
    return -1
